import{_ as o}from"./chunks/settings-cal.pc.ko.DNqctmh_.js";import{_ as d}from"./chunks/settings-robot.pc.ko.GwDViD4u.js";import{_ as t,o as c,c as a,a5 as r}from"./chunks/framework.BjM_ivYE.js";const i="/RBQ/images/app/settings-app.pc.ko.png",_=JSON.parse('{"title":"설정","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/settings.md","filePath":"ko/manual/gui/settings.md","lastUpdated":1790654982000}'),l={name:"ko/manual/gui/settings.md"};function n(s,e,h,p,m,u){return c(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="설정" tabindex="-1">설정 <a class="header-anchor" href="#설정" aria-label="Permalink to &quot;설정&quot;">​</a></h1><p>설정은 두 벌로 나뉩니다. 각 벌의 섹션은 화면 위쪽에 칩으로 늘어서고, 폰에서는 아이콘만 나옵니다.</p><ul><li><strong>로봇 설정</strong>은 고른 로봇에 딸린 설정입니다. 허브의 <code>로봇 설정</code> 타일로 엽니다. 섹션: <code>캘리브레이션</code>, <code>전원 제어</code>, <code>페이로드 설정</code>, <code>소프트웨어 업데이트</code>. 제목에는 <code>로봇</code>과 로봇 이름·시리얼이 표시됩니다.</li><li><strong>앱 설정</strong>은 이 기기에 딸린 설정입니다. 허브나 하위 화면 오른쪽 위의 톱니 버튼으로 엽니다. 섹션: <code>게임패드</code>, <code>앱 설정</code>. 제목에는 <code>앱</code>과 기기·앱 버전이 표시됩니다.</li></ul><p>설정 화면 왼쪽 위의 로고를 누르면 허브로 돌아가고, 그 옆 게임패드 버튼을 누르면 곧바로 제어 화면으로 갑니다. 이 버튼은 로봇이 연결됐거나 시뮬을 켠 동안에만 눌립니다.</p><ul><li>로봇 연결은 허브의 로봇 목록에서 합니다. <a href="/RBQ/ko/manual/gui/connection.html">연결</a>을 참고하세요.</li><li><code>게임패드</code>는 <a href="/RBQ/ko/manual/gui/gamepad.html">게임패드</a>에서 다룹니다.</li><li><code>소프트웨어 업데이트</code>는 <a href="/RBQ/ko/manual/gui/software-update.html">소프트웨어 업데이트</a>에서 다룹니다.</li></ul><p>이 페이지는 나머지 네 섹션을 설명합니다. 모두 운용자가 사용할 수 있으며, 개발자 모드가 필요한 항목은 따로 표시했습니다.</p><h2 id="calibration" tabindex="-1">캘리브레이션 <a class="header-anchor" href="#calibration" aria-label="Permalink to &quot;캘리브레이션 {#calibration}&quot;">​</a></h2><p><img src="'+o+'" alt="캘리브레이션 섹션"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>여기의 모든 보정은 로봇을 평지에 <strong>정지</strong> 상태로 두고 실행해야 합니다. 로봇이 걷고 있거나 넘어졌거나 상태를 보내지 않으면 IMU·ZMP 행이 막힙니다. 명령을 보내기 전에는 <code>보정을 실행할까요?</code> 확인이 먼저 뜹니다. 관절 홈포즈 세팅은 확인 창을 따로 씁니다. 보정이 끝날 때까지 로봇을 건드리지 마세요.</p></div><h3 id="imu-캘리브레이션" tabindex="-1">IMU 캘리브레이션 <a class="header-anchor" href="#imu-캘리브레이션" aria-label="Permalink to &quot;IMU 캘리브레이션&quot;">​</a></h3><table tabindex="0"><thead><tr><th>행</th><th>동작</th></tr></thead><tbody><tr><td><code>가속도계 보정 (ACC)</code></td><td>가속도계 드리프트를 현장에서 보정합니다. <strong>로봇을 앉힌 상태로</strong> 평지에 두고 실행하며, 약 2초 동안 중력 크기를 평균 내 보정계수를 저장합니다.</td></tr><tr><td><code>IMU 롤/피치 영점</code></td><td>현재 자세를 수평 기준으로 삼습니다. 약 0.5초 — 기울어진 상태로 실행하면 이후 제어가 전부 틀어집니다.</td></tr><tr><td><code>자이로 바이어스 보정</code></td><td>IMU를 리셋하고 값이 자리 잡기를 기다린 뒤 자이로 값을 다시 측정합니다. 약 5초, <strong>로봇을 앉힌 상태로</strong> 실행합니다. 끝나면 세 축의 값과 각 축이 허용치 안에 드는지를 알려 줍니다. 그래도 편차가 허용치를 넘으면 로봇을 완전히 멈춰 둔 채로 다시 실행하십시오.</td></tr></tbody></table><p><code>실행</code>을 누른 뒤 대화상자에서 <code>실행</code>으로 확정합니다. 막혀 있으면 이유를 알려 주고, 앱이 직접 풀 수 있는 것이면 <code>실행</code> 옆에 버튼이 하나 생깁니다 — 앉아야 하면 <code>앉기</code>, 서야 하면 <code>서기</code>, 제어가 꺼져 있으면 <code>자동 기동</code>입니다(이 버튼은 확인 창이 먼저 뜹니다). 넘어졌거나 도킹 중이거나 상태가 오지 않을 때는 버튼이 나오지 않습니다.</p><p><code>IMU 롤/피치 영점</code>은 확인 창의 수평계 아래에 현재 롤·피치를 보여 주고, 실행하는 동안 진행 창이 뜹니다. 롤·피치가 모두 1° 안으로 들어왔을 때만 <code>성공</code>으로 끝나고, 로봇이 아직 기울어 있으면 <code>영점이 반영되지 않았을 수 있습니다</code> 가 대신 뜹니다 — 평지에 두고 다시 실행하십시오.</p><h3 id="무게-중심-보정-zmp" tabindex="-1">무게 중심 보정 (ZMP) <a class="header-anchor" href="#무게-중심-보정-zmp" aria-label="Permalink to &quot;무게 중심 보정 (ZMP)&quot;">​</a></h3><p><code>무게 중심 오프셋 자동 보정</code>은 무게중심 오프셋을 자동으로 찾습니다. 로봇이 평지에서 STAND 상태여야 합니다. 다리를 나란히 맞추려고 한 걸음 걸은 뒤, 수렴할 때까지 최대 60초가 걸립니다. 오프셋이 수렴하면 로봇이 스스로 저장하고 STAND로 돌아옵니다. 패널에 진행 상황과 완료 메시지가 표시됩니다.</p><h3 id="관절-캘리브레이션" tabindex="-1">관절 캘리브레이션 <a class="header-anchor" href="#관절-캘리브레이션" aria-label="Permalink to &quot;관절 캘리브레이션&quot;">​</a></h3><p>다리 관절의 영점·오프셋을 다시 잡습니다. 로봇을 <strong>앉힌 상태</strong>로 실행합니다.</p><table tabindex="0"><thead><tr><th>행</th><th>동작</th></tr></thead><tbody><tr><td><code>관절 홈포즈 세팅</code></td><td>치구로 홈 자세를 고정한 뒤 그 자세를 관절 영점으로 저장 — 다리 4개</td></tr><tr><td><code>DQ 오프셋 보정</code></td><td><code>준비 중</code> — 자리만 잡혀 있고 누를 수 없습니다</td></tr></tbody></table><p><code>관절 홈포즈 세팅</code>을 누르면 창이 둘 열립니다. 먼저 고지(<em>관절 영점을 다시 쓰는 조작입니다 — 치구가 없거나 자세가 어긋난 상태로 실행하면 로봇이 잘못된 영점으로 기동합니다</em>), 그다음 다리별 화면입니다. 그 화면에서 맞출 관절을 고릅니다. 고른 관절은 왼쪽 3D 뷰에서 목표 자세까지 움직입니다. 치구를 끼워 그 자세를 만든 뒤 <code>LEG{n} - {g} 홈포즈 저장</code>을 누릅니다. 영점을 쓰는 순간 제어가 꺼지므로(BOARD_RESET) 로봇을 먼저 앉히십시오. 서 있으면 그대로 주저앉습니다. 치구가 필요합니다.</p><p>모터 보드와 통신이 없으면 행이 막히고 <em>모터 보드와 통신이 없습니다 — 48V 구동(LEGS) 전원을 켠 뒤 다시 실행하세요.</em> 가 뜹니다. 그 레일은 <a href="/RBQ/ko/manual/gui/maintenance.html">정비</a>에 있습니다.</p><h3 id="카메라-캘리브레이션" tabindex="-1">카메라 캘리브레이션 <a class="header-anchor" href="#카메라-캘리브레이션" aria-label="Permalink to &quot;카메라 캘리브레이션&quot;">​</a></h3><blockquote><p><strong>개발자 모드에서 더 나오는 것</strong>은 <a href="/RBQ/ko/manual/gui/developer-mode.html#settings">개발자 모드</a>에 모아 두었습니다.</p></blockquote><h3 id="도킹-캘리브레이션" tabindex="-1">도킹 캘리브레이션 <a class="header-anchor" href="#도킹-캘리브레이션" aria-label="Permalink to &quot;도킹 캘리브레이션&quot;">​</a></h3><p>캘리브레이션 섹션 맨 아래에 자동 도킹 정렬 파라미터가 있습니다: <code>Offset X (m)</code>, <code>Offset Y (m)</code>, <code>Req Count</code>, <code>Try Count</code>.</p><ul><li><code>다시 읽기</code> — 로봇에서 값을 다시 읽어옵니다.</li><li><code>기본값</code> — 입력칸을 출고 기본값으로 채웁니다. <code>적용</code>을 누르기 전에는 저장되지 않습니다.</li><li><code>적용</code> — 값을 로봇에 저장하고 다시 읽어 확인합니다.</li></ul><h2 id="전원-제어" tabindex="-1">전원 제어 <a class="header-anchor" href="#전원-제어" aria-label="Permalink to &quot;전원 제어&quot;">​</a></h2><p>일상 운용에서 켜고 끄는 보조 전원을 다룹니다. 토글은 로봇이 보고한 실제 PDU 상태를 그대로 보여 줍니다. 그래서 눌러도 화면에 반영되기까지 1초쯤 걸릴 수 있습니다. 레일 상태가 처음 들어오기 전에는 토글이 꺼진 채로 있습니다.</p><p><strong>12 V 토글</strong>(한 번 탭): <code>스피커 앰프 (12V)</code>, <code>CCTV (12V)</code>, <code>열화상 (12V)</code>, <code>IR LED (12V)</code>.</p><p><strong>48 V 레일</strong>(2단계): <code>ARM · ADDON (48V)</code>, <code>EXTERN (48V)</code> 각각 현재 전압과 <code>끄기</code> / <code>켜기</code> 버튼이 있습니다. 누르면 <code>정말 끌까요?</code> / <code>정말 켤까요?</code>가 뜨고, 확정하면 전환됩니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>ARM · ADDON (48V)</code>는 팔과 애드온이 PDU 포트 하나를 함께 씁니다. 이 레일을 끄면 팔 전원도 함께 나가므로 팔이 정지 상태인지 먼저 확인하세요.</p></div><p>카메라·통신·Vision PC·LEGS(48 V) 전원, LiDAR, 시스템 재부팅은 여기 없습니다. 끄면 연결이 끊기거나 로봇이 주저앉는 조작이라 <a href="/RBQ/ko/manual/gui/maintenance.html">정비</a>(개발자 모드)에 있습니다.</p><h2 id="robot-parameters" tabindex="-1">페이로드 설정 <a class="header-anchor" href="#robot-parameters" aria-label="Permalink to &quot;페이로드 설정 {#robot-parameters}&quot;">​</a></h2><p><img src="'+d+'" alt="로봇 파라미터 섹션"></p><p><code>로봇 페이로드 설정</code>에는 로봇에 실은 적재물을 적어 둡니다. 이 값이 보행 동역학에 반영됩니다.</p><ol><li>로봇은 13개의 페이로드 슬롯을 보고합니다. 슬롯을 체크해 장착으로 표시하고 질량과 무게중심(X, Y, Z)을 입력합니다.</li><li>하단에 합계 질량과 합성 무게중심이 표시되며, 합계가 상한을 넘으면 경고합니다.</li><li><code>Set Payload</code>를 누르고 <code>적용</code>으로 확정합니다(<code>Get</code>은 로봇의 슬롯을 다시 읽어 편집 내용을 버립니다). 확인 창에 장착 슬롯 수와 합계가 표시되고, 체크 해제한 슬롯은 질량 0으로 전송됩니다. 새 값은 즉시 보행 동역학에 반영되며 1~2초에 걸쳐 천천히 적용됩니다.</li></ol><p><code>도움말</code>을 누르면 표 위에 짧은 안내가 펼쳐집니다. 페이로드 슬롯 API가 없는 로봇에서는 로봇 소프트웨어 갱신을 안내하는 문구가 대신 표시됩니다.</p><h2 id="앱-설정" tabindex="-1">앱 설정 <a class="header-anchor" href="#앱-설정" aria-label="Permalink to &quot;앱 설정&quot;">​</a></h2><p><img src="'+i+'" alt="앱 설정 섹션"></p><p>로봇이 아니라 앱 자체의 환경설정입니다.</p><table tabindex="0"><thead><tr><th>행</th><th>옵션</th></tr></thead><tbody><tr><td><code>테마</code></td><td><code>다크</code> / <code>라이트</code></td></tr><tr><td><code>언어 / Language</code></td><td><code>한국어</code> / <code>English</code> — 즉시 적용</td></tr><tr><td><code>조이스틱 감도</code></td><td>슬라이더 — 입력 응답 곡선</td></tr><tr><td><code>화면 항상 켜기</code></td><td>토글 — 제어 중 화면 유지</td></tr><tr><td><code>데드존</code></td><td>슬라이더 — 조이스틱 중심 무시 범위</td></tr><tr><td><code>Gyro 위젯</code></td><td>토글 — 롤/피치 자세계 표시</td></tr><tr><td><code>전체화면</code></td><td>토글 — 브라우저 전용</td></tr><tr><td><code>저신호 경고</code></td><td>토글 — Wi-Fi 신호가 <code>경고 임계</code>(<code>Warning threshold</code>, 켜져 있을 때 표시되는 슬라이더) 미만이면 상단 경고 배너</td></tr><tr><td><code>경고 비프 (Notify BEEP)</code></td><td>토글 — 경고 시 짧은 알림음(웹 전용)</td></tr><tr><td><code>배터리 부족 경고음</code></td><td>토글 — 로봇 배터리가 부족하면 알림음. <code>경고 비프 (Notify BEEP)</code>가 켜져 있어야 합니다(웹 전용)</td></tr><tr><td><code>UI 배율</code></td><td>데스크탑 앱 전용 — <code>자동</code>, 100 %~200 %</td></tr></tbody></table><h3 id="developer-mode" tabindex="-1">개발자 모드 <a class="header-anchor" href="#developer-mode" aria-label="Permalink to &quot;개발자 모드 {#developer-mode}&quot;">​</a></h3><p><code>개발자 모드</code> 토글은 오른쪽 위 톱니 옆 둥근 버튼을 누르면 나오는 프로필 메뉴에 있습니다. 게스트 상태에서는 <code>개발자 모드</code>를 켜고 암호를 넣으면 됩니다. 다시 끄면 운용자 레벨로 돌아갑니다. 접근 코드로 로그인한 동안(같은 메뉴의 <code>접근 코드로 로그인</code>)에는 계정이 레벨을 결정하므로 토글이 나오지 않습니다.</p><p>개발자 모드를 켜면 허브의 <code>정비</code> 타일, 위의 개발자 전용 행, <code>모션 선택</code> 그리드의 <code>AI 모션</code>·<code>포지션 제어</code> 그룹이 추가됩니다.</p>',43)])])}const k=t(l,[["render",n]]);export{_ as __pageData,k as default};
